    /**
    * Calls:
    * 1 - (201) POST:/petclinic/api/owners
    * 2 - (404) POST:/petclinic/api/owners/{ownerId}/pets
    * Using 6 examples:
    *   (-) BODY -> 1
    *   (-) BODY -> 110 W. Liberty St.
    *   (-) BODY -> 6085551023
    *   (-) BODY -> George
    *   (-) BODY -> Madison
    *   (-) BODY -> cat
    */
    @Test @Timeout(60)
    public void test_35_postOnPetsReturns404() throws Exception {
        
        ValidatableResponse res_0 = given().accept("application/json")
                .contentType("application/json")
                .body(" { " + 
                    " \"firstName\" : \"George\", " + 
                    " \"lastName\" : \"Escobito\", " + 
                    " \"address\" : \"110 W. Liberty St.\", " + 
                    " \"city\" : \"Madison\", " + 
                    " \"telephone\" : \"6085551023\" " + 
                    " } ")
                .post(baseUrlOfSut + "/petclinic/api/owners")
                .then()
                .statusCode(201)
                .assertThat()
                .contentType("application/json")
                .body("'firstName'", containsString("George"))
                .body("'lastName'", containsString("Escobito"))
                .body("'address'", containsString("110 W. Liberty St."))
                .body("'city'", containsString("Madison"))
                .body("'telephone'", containsString("6085551023"))
                .body("'pets'.size()", equalTo(0));
        String location_owners__2 = res_0.extract().header("location");
        assertTrue(isValidURIorEmpty(location_owners__2));
        
        given().accept("*/*")
                .contentType("application/json")
                .body(" { " + 
                    " \"name\" : \"UbdmSJ\", " + 
                    " \"birthDate\" : \"2063-02-04\", " + 
                    " \"type\" : { " + 
                    " \"name\" : \"cat\", " + 
                    " \"id\" : 1 " + 
                    " } " + 
                    " } ")
                .post(resolveLocation(location_owners__2, baseUrlOfSut + "/petclinic/api/owners/944/pets"))
                .then()
                .statusCode(404)
                .assertThat()
                .contentType("text/html");
        
        // Cleanup actions
        given().accept("*/*")
                .delete(resolveLocation(location_owners__2, baseUrlOfSut + "/petclinic/api/owners/53"))
                .then()
                .statusCode(404)
                .assertThat()
                .contentType("text/html");
    }
    
    
